 void compatible(JvmClass next)throws Exception{if(!name.equals(next.name)||!parent.equals(next.parent)||!interfaces.equals(next.interfaces)||(access&0x631)!=(next.access&0x631))throw new IOException("Jerarquía/acceso incompatible: "+name);for(Map.Entry<String,String> f:fields.entrySet())if(!f.getValue().equals(next.fields.get(f.getKey())))throw new IOException("Cambió un campo o constante en línea: "+name+"#"+f.getKey());for(Map.Entry<String,String> m:methods.entrySet())if(!m.getValue().equals(next.methods.get(m.getKey())))throw new IOException("Falta o cambió una firma del núcleo: "+name+"#"+m.getKey());}
